/* Settings */
.test-card{
  --_test-card__content-padding: var(--test-card__content-padding, var(--space-s));
  --_test-card__media-max-width: var(--test-card__media-max-width, 200px);
  --_test-card__media-min-height: var(--test-card__media-min-height, 150px);
  --_test-card-background: var(--test-card-background, var(--light));
  --_test-card-border-radius: var(--test-card-border-radius, var(--radius-m));
  --_test-card-box-shadow: var(--test-card-box-shadow, var(--shadow-m));

  --_test-card-border: var(--test-card-border, none);
}

:has(> .test-card) {
  container-type: inline-size;
}

.test-card {
  display: flex;
  overflow: clip;
  flex-direction: row;
  border-radius: var(--_test-card-border-radius);
  box-shadow: var(--_test-card-box-shadow);
  background: var(--_test-card-background);
  width: 100%;
  border: var(--_test-card-border);

  @container (inline-size <=562px) {
    flex-direction: column;

    .test-card__media {
      flex: auto;
      max-width: 100%;
    }
  }
}

.test-card__content {
  flex: 1 1 0;
  min-width: 0;
  padding: var(--_test-card__content-padding);
}

.test-card__media {
  order: -1;
  flex: 0 0 auto;
  width: 100%;
  max-width: var(--_test-card__media-max-width);
  min-height: var(--_test-card__media-min-height);
}

/* Settings */
.test-card--style2{
  --test-card__content-padding: var(--space-s);
  --test-card-background: var(--light);
  --test-card-border-radius: var(--radius-m);
  --test-card-box-shadow: var(--shadow-l);
  --test-card__media-max-width: 250px;
  --test-card__media-min-height: 180px;
  --test-card-border: 2px solid var(--base-l-2);
}
